Você é um juiz, avaliando se uma resposta satisfaz as rúbricas fornecidas. Para cada rúbrica, se a resposta satisfaz o critério da rúbrica, produza YES; caso contrário, produza NO.

Requisito:
- Você deve seguir cada rúbrica estritamente, e apenas considerar os critérios listados na rúbrica.
- Você NÃO deve considerar quaisquer outros fatores, como suas próprias opiniões ou conhecimento externo.

## Consulta Atual do Usuário
<|begin_of_query|>

Crie um HTML com CSS e JS embutido, que seja bonito e tenha as seguintes funcionalidades. O site deverá receber um texto inserido pelo usuário. O usuário também irá inserir em local específico qual texto, incluíndo símbolos, ele quer retirar do texto. Deverão existir 5 espaços para receber esse texto que será excluído, para que sejam excluídos todos de uma vez. Após, o texto aparecerá já com os textos retirados. deverá ter um botão para copiar o texto já trabalhado. O nome do HTMl site deverá ser algo do tipo Super retirador de texto do Paps (crie um nome que tenha esse significado e que seja bacana).

<|end_of_query|>

Abaixo entre <RESPONSE> e </RESPONSE> está a resposta a ser avaliada:
<RESPONSE>


Prontinho! Criei um site completo em **um único arquivo HTML** (com CSS e JS embutidos), bonito e moderno, com todas as funcionalidades que você pediu. O nome escolhido foi **"Super Retirador de Texto Paps"** — mantendo a marca **Paps** com um toque divertido. 👇

## Como usar
1. Copie o código abaixo, cole em um Bloco de Notas e salve como **`super-retirador-paps.html`**
2. Abra no Chrome/Edge/Firefox (funciona **offline**, sem internet)
3. Cole seu texto no campo grande, digite os padrões/símbolos que quer remover nos 5 campos e clique em **🧹 Limpar**
4. Acompanhe as contagens sendo feitas e, no fim, use **📋 Copiar!**

---

```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="Super Retirador de Texto Paps: remova palavras, pontuação, símbolos e caracteres do seu texto de uma só vez. Interface simples e rápida!">
<title>Super Retirador de Texto Paps — Elimine textos e símbolos rapidinho</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Poppins:ital,wght@0,300;0,400;0,500;0,600;0,700&display=swap" rel="stylesheet">
<style>
  /* ════════════════════════════════════════════════════
     SUPER RETIRADOR DE TEXTO PAPS │ Estilo
     ════════════════════════════════════════════════════ */
  *,*::before,*::after{box-sizing:border-box}
  html{scroll-behavior:smooth;-moz-text-size-adjust:100%;-webkit-text-size-adjust:100%}
  body{
    margin:0;min-height:100dvh;font-family:'Poppins',system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;
    color:var(--txt);line-height:1.6;cursor:text;
    background:
      linear-gradient(158deg,var(--bg1),var(--bg2)),
      radial-gradient(600px 460px 52% at 6% 100%, rgba(0,201,168,.09), transparent 60%),
      radial-gradient(820px 540px 50% at 94% -10%, rgba(123,95,255,.15), transparent 60%);
    background-size:cover;
    animation:gradear 16s ease-in-out infinite;
  }
  @keyframes gradear{
    0%   { background-position:0 0; }
    100% { background-position:200% 130%; }
  }
  @media (prefers-reduced-motion:reduce){ body{animation:none} }
  ::selection{background:rgba(123,95,255,.42);color:#fff}

  /* Variáveis de tema */
  :root{
    --bg1:#0b0e16; --bg2:#162035;
    --card:#172033; --card2:#1e2c40; --limite:#2a374a; --limite-borda:#2d394c;
    --txt:#e6eaf0; --muted:#9ab0c6;
    --glow:#7b5ffa; --ring:#a29bfe; --ombra:0 14px 46px rgba(0,0,0,.52); --rn:18px;
  }
  .light-mode{
    --bg1:#eceef3; --bg2:#dfe8f6;
    --card:#fff; --card2:#f2f6fb; --limite:#d6dee8; --limite-borda:#cdbfe2;
    --txt:#182437; --muted:#5d6b7e;
    --glow:#6c5ce7; --ring:#6c5ce7; --ombra:0 8px 22px rgba(24,36,55,.08);
  }

  /* Layout geral */
  .app{max-width:1140px;margin:0 auto;padding:0 16px 50px;display:flex;flex-direction:column;gap:22px}
  .hero{padding:24px 0 8px;text-align:left}
  .row-titulo{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;flex-wrap:wrap}
  .hero h1{
    font-size:clamp(1.8rem,4.7vw,2.6rem);font-weight:700;letter-spacing:-.02em;line-height:1.12;margin:0 0 8px;
    background:var(--accent);-webkit-background-clip:text;background-clip:text;color:transparent;
  }
  .tagline{max-width:740px;color:var(--muted);font-size:clamp(.92rem,1.5vw,1rem)}
  .trocar-tema{
    position:relative;width:40px;height:40px;border-radius:50%;
    border:2px solid var(--limite-borda);background:var(--card);
    color:var(--muted);cursor:pointer;font-size:.85rem;display:flex;align-items:center;justify-content:center;
    transition:.25s all;box-shadow:0 2px 10px rgba(0,0,0,.3);
  }
  .trocar-tema:hover{transform:scale(1.08);border-color:var(--glow);background:rgba(123,95,255,.16);color:#fff}
  .trocar-tema:active{transform:scale(.93)}

  /* Formulário */
  .sec-form{display:flex;flex-direction:column;gap:14px}
  .caixa-entrada{position:relative;flex:1 1 540px;min-height:92px}
  .caixa-entrada .rotulo{
    position:absolute;top:11px;left:12px;font-size:.7rem;font-weight:600;
    letter-spacing:.05em;text-transform:uppercase;color:var(--muted);opacity:.85;pointer-events:none;
  }
  #txtEntrada{
    width:100%;max-width:560px;appearance:none;background:var(--card);
    border:1.5px solid var(--limite-borda);border-radius:var(--rn);
    color:var(--txt);font:inherit;padding:12px 13px;
    resize:vertical;overflow:hidden;line-height:1.45;min-height:92px;
    transition:border-color .25s,box-shadow .25s;
  }
  #txtEntrada:focus{outline:none;border-color:var(--ring);box-shadow:0 0 0 5px rgba(162,155,255,.16)}
  #txtEntrada::-webkit-scrollbar{width:6px;height:6px}
  #txtEntrada::-webkit-scrollbar-thumb{background:rgba(255,255,255,.15);border-radius:3px}
  .hint-abre{position:absolute;bottom:10px;left:12px;font-size:.68rem;color:var(--muted);opacity:.75;pointer-events:none;word-break:break-all}
  .grid-passo{display:flex;gap:10px;flex-wrap:wrap}
  .passo{
    flex:0 0 auto;min-width:192px;
    background:var(--card);border:1.5px solid var(--limite-borda);
    border-radius:var(--rn);padding:13px 11px 10px;
    display:flex;flex-direction:column;gap:6px;
    transition:border-color .3s,transform .2s,box-shadow .25s;
  }
  .passo:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.34)}
  .numero-passo{
    flex:none;margin-right:7px;
    display:inline-flex;align-items:center;justify-content:center;
    width:28px;height:28px;border-radius:50%;
    background:rgba(123,95,255,.15);border:1.5px solid rgba(123,95,255,.45);
    color:var(--glow);font-size:.74rem;font-weight:700;
  }
  .passo .num{
    display:inline-flex;align-items:center;justify-content:center;
    width:28px;height:28px;border-radius:50%;
    background:rgba(123,95,255,.15);border:1.5px solid rgba(123,95,255,.45);
    color:#fff;font-size:.74rem;font-weight:700;flex:none;margin-right:8px;
  }
  .passo .nome{font-size:.8rem;font-weight:600;letter-spacing:.02em}
  .passo .extra{font-size:.7rem;color:var(--muted);font-style:italic}
  .passo .exemp{font-size:.64rem;color:var(--muted);margin-top:2px;word-break:keep-all}
  .badge-pn{
    flex:none;margin-right:auto;
    display:inline-flex;align-items:center;justify-content:center;
    width:24px;height:24px;border-radius:50%;
    background:rgba(162,155,255,.14);border:1px solid rgba(162,155,255,.42);
    color:#cdd5ff;font-size:.66rem;font-weight:700;
    opacity:0;pointer-events:none;transition:.2s all;
  }
  .in-step.has-badge .badge-pn{opacity:1;pointer-events:auto}
  .in-step.no-badge .badge-pn{opacity:0;pointer-events:none;transform:scale(.5)}
  .in-step{
    width:100%;appearance:none;background:var(--card);
    border:1.5px solid var(--limite-borda);
    border-radius:calc(var(--rn)-4px);
    color:var(--txt);font:inherit;padding:10px 12px;
    resize:none;overflow:hidden;line-height:1.4;min-height:44px;
    transition:border-color .25s,box-shadow .25s;
  }
  .in-step:focus{outline:none;border-color:var(--ring);box-shadow:0 0 0 4px rgba(162,155,255,.15)}

  /* Ações */
  .acoes{display:flex;align-items:center;flex-wrap:wrap;justify-content:center;gap:10px;padding:8px 0}
  .botao{
    display:inline-flex;align-items:center;gap:9px;
    padding:11px 19px;font:inherit;font-weight:600;color:#fff;
    border:none;border-radius:var(--rn);background:var(--accent);
    cursor:pointer;transition:.22s all;white-space:nowrap;
    box-shadow:0 6px 22px rgba(123,95,255,.38);
  }
  .botao:hover:not(:disabled){transform:scale(1.02);filter:brightness(1.08);box-shadow:0 8px 30px rgba(123,95,255,.55)}
  .botao:active{transform:scale(.98);filter:brightness(.95)}
  .botao:disabled{opacity:.5;cursor:wait;transform:none;filter:brightness(1)}
  .botao.zerar{background:transparent;border:2px solid var(--glow);color:var(--glow);box-shadow:none}
  .botao.zerar:hover:not(:disabled){background:rgba(123,95,255,.08);transform:scale(1.02)}
  .ativando .spi{
    display:inline-block;width:15px;height:15px;border:3px solid rgba(255,255,255,.16);
    border-top-color:#fff;border-radius:50%;animation:giro .75s linear infinite;margin-right:7px;vertical-align:middle;flex:none;
  }
  @keyframes giro{to{transform:rotate(360deg)}}
  .aviso-xs{font-size:.72rem;color:var(--muted);margin-left:10px;flex:none;white-space:nowrap}

  /* Resultado */
  .sec-resumo{
    background:var(--card);border:1px solid var(--limite-borda);
    border-left:5px solid var(--glow);border-radius:var(--rn);
    padding:18px 22px 18px;box-shadow:var(--ombra);position:relative;overflow:hidden;
  }
  .sec-resumo::before{
    content:'';position:absolute;inset:0;
    background:linear-gradient(180deg,transparent 0%,rgba(123,95,255,.04) 45%,rgba(123,95,255,.22) 100%);
  }
  .cabecRes{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:16px}
  .cabecRes .rotulo2{font-size:.74rem;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
  .estatisticas{display:flex;gap:10px;flex-wrap:wrap}
  .stat-item{display:flex;align-items:center;gap:7px;font-size:.74rem;color:var(--muted)}
  .stat-item .pontinho{width:8px;height:8px;border-radius:50%;background:var(--glow)}
  .outro{
    width:100%;appearance:none;background:transparent;
    border:1px solid var(--limite-borda);border-radius:var(--rn);
    color:var(--txt);font:inherit;padding:14px 14px;
    resize:vertical;overflow:hidden;line-height:1.5;min-height:130px;
    transition:border-color .25s,box-shadow .25s;
  }
  .outro:focus{outline:none;border-color:var(--ring);box-shadow:0 0 0 4px rgba(162,155,255,.16)}
  .outro::placeholder{color:var(--muted)}
  .area-copiar{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:14px}

  /* Notificações */
  .bar-notif{position:fixed;top:14px;right:14px;z-index:9999;flex-direction:column;gap:8px;width:min(360px,92vw);pointer-events:none;overflow:hidden}
  .notif{
    pointer-events:auto;max-height:270px;overflow:hidden;
    background:rgba(17,24,40,.93);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);
    border:1px solid rgba(123,95,255,.3);border-left:4px solid #3fb950;
    border-radius:13px;padding:12px 15px;color:#e6eaf1;
    font:inherit;display:flex;align-items:center;gap:11px;
    box-shadow:0 10px 26px rgba(0,0,0,.55);
    animation:entrar .3s cubic-bezier(.2,0,.2,1) forwards;
  }
  .notif.alerta{border-left-color:#ffb84c}
  .notif.erro{border-left-color:#f0a500}
  .notif strong{font-weight:600}
  .notif .marca{font-size:1rem;line-height:1}
  .notif.saia{animation:sair .26s ease forwards}
  @keyframes entrar{from{transform:translateY(32px) scale(.94);opacity:0} to{transform:translateY(0) scale(1);opacity:1}}
  @keyframes sair{from{transform:translateY(0) scale(1);opacity:1} to{transform:translateY(42px) scale(.88);opacity:0}}

  footer{margin-top:8px;color:var(--muted);font-size:.7rem;text-align:center}
</style>
</head>
<body>

<!-- ═════════ HERO ═════════ -->
<section class="hero">
  <div class="row-titulo">
    <div>
      <h1>Super Retirador de Texto Paps</h1>
      <p class="tagline">
        Seu texto, sem bagunça: apague palavras, pontuações e símbolos numa única ação com apenas um clique.
        Tudo feito com carinho pelo <strong>Paps</strong> ✨
      </p>
    </div>
    <button class="trocar-tema" aria-label="Alterar entre tema claro e escundo" title="Temas">
      <svg class="icone-luna base" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:20px;height:20px">
        <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>
      </svg>
      <svg class="icone-sol base" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:20px;height:20px">
        <circle cx="12" cy="12" r="5"/>
        <line x1="12" y1="1" x2="12" y2="3"/>
        <line x1="12" y1="21" x2="12" y2="23"/>
        <line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/>
        <line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/>
        <line x1="1" y1="12" x2="3" y2="12"/>
        <line x1="21" y1="12" x2="23" y2="12"/>
        <line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/>
        <line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/>
      </svg>
    </button>
  </div>
</section>

<!-- ═════════ FORMULÁRIO ═════════ -->
<main class="app">
  <section class="sec-form">
    <div class="caixa-entrada">
      <label for="txtEntrada" class="rotulo">Seu texto original ⬆️</label>
      <textarea id="txtEntrada" class="" placeholder="Cole aqui todo o seu texto, com tudo o que estiver... (mantém quebras de linha)"><span class="hint-abre">Ou cole de fora — pode ter parágrafos, emojis e o que for preciso 😉</span></textarea>
    </div>

    <div class="grid-passo">
      <!-- Passo 1 -->
      <div class="passo" data-id="1">
        <div class="numero-passo">1</div>
        <span class="nome">Passo 1 · Palavras soltas</span>
        <span class="extra">✂️ Palavra ou chamada repetida</span>
        <span class="exemp">Ex.: digite "super"</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false" autofocus>
        <div class="status-linha esperando">— aguardando padrão</div>
      </div>

      <!-- Passo 2 -->
      <div class="passo" data-id="2">
        <div class="numero-passo">2</div>
        <span class="nome">Passo 2 · Pontuação pesada</span>
        <span class="extra">⚡ Pontos, interrogações e afins</span>
        <span class="exemp">Ex.: "! ? ."</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false">
        <div class="status-linha esperando">— aguardando padrão</div>
      </div>

      <!-- Passo 3 -->
      <div class="passo" data-id="3">
        <div class="numero-passo">3</div>
        <span class="nome">Passo 3 · Símbolos conhecidos</span>
        <span class="extra">🧾 Símbolos que poluem o texto</span>
        <span class="exemp">Ex.: "@ # $ %"</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false">
        <div class="status-linha esperando">— aguardando padrão</div>
      </div>

      <!-- Passo 4 -->
      <div class="passo" data-id="4">
        <div class="numero-passo">4</div>
        <span class="nome">Passo 4 · Outros caracteres</span>
        <span class="extra">🪝 Asteriscos, chaves, barras e mais</span>
        <span class="exemp">Ex.: "* + - _ { } | <<>>"</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false">
        <div class="status-linha esperando">— aguardando padrão</div>
      </div>

      <!-- Passo 5 -->
      <div class="passo" data-id="5">
        <div class="numero-passo">5</div>
        <span class="nome">Passo 5 · Esconderijos finais</span>
        <span class="extra">👹 Emoji, códigos e sobras digitais</span>
        <span class="exemp">Digite qualquer coisa estranha</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false">
        <div class="status-linha esperando">— aguardando padrão</div>
      </div>
    </div>

    <div class="acoes">
      <button class="botao" id="btnLimpar" type="button">🧹 Limpar (aplica TODOS os padrões)</button>
      <span class="aviso-xs">Comparação exata — maiúsculas importam</span>
      <button class="botao zerar" id="btnZERAR" type="button">↺ Zerar tudo</button>
    </div>
  </section>

  <!-- ═════════ RESULTADO ═════════ -->
  <section class="sec-resumo">
    <div class="cabecRes">
      <span class="rotulo2">Resultado</span>
      <div class="estatisticas"></div>
    </div>
    <textarea id="resTexto" class="outro" rows="10" placeholder="Aqui está seu texto já limpinho ✨ (aguarde o processamento…)"></textarea>
    <div class="area-copiar">
      <button class="botao rj" id="btnCopiar" type="button" disabled>📋 Copiar resultado</button>
    </div>
  </section>
</main>

<footer>© 2026 Super Retirador de Texto Paps · Feito com carinho e código limpo 💜</footer>

<script>
(function(){ "use strict";

  /* ═════════ CONFIGURAÇÃO ═════════ */
  const PASSOS = [
    { id:1, nome:'Passo 1', extra:'✂️ Palavra ou chamada repetida',   exemp:'Ex.: digite "super"' },
    { id:2, nome:'Passo 2', extra:'⚡ Pontuação pesada',              exemp:'Ex.: "! ? ." ' },
    { id:3, nome:'Passo 3', extra:'🧾 Símbolos conhecidos',           exemp:'Ex.: "@ # $ %"' },
    { id:4, nome:'Passo 4', extra:'🪝 Outros caracteres',             exemp:'Ex.: "* + - _ { } | <<>>"' },
    { id:5, nome:'Passo 5', extra:'👹 Emoji e códigos',                exemp:'Qualquer coisa estranha' },
  ];
  const TAMPO_TEMA   = 'pps_tema';
  const BUSCA_NOTIF  = document.querySelector('.bar-notif');

  /* ═════════ UTILITÁRIOS ═════════ */
  function escHTML2(t){
    return String(t != null ? t : '')
      .replace(/[&<>"']/g, function(ch){
        return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'": '&#39;' }[ch];
      });
  }
  function escaparPadrao(s){
    // transforma símbolos em sequências seguras para regex (evita erros de sintaxe)
    return s.replace(/[.*+?^${}()|[\]\\]/g, function(m){ return '\\' + m; });
  }
  function contarPadrao(valorCompleto, padrao){
    try{ return (valorCompleto.match(new RegExp(escaparPadrao(padrao),'g')) || []).length; }
    catch(e){ return 0; }
  }

  /* ═════════ TEMA CLARO / ESCURO ═════════ */
  function carregarTema(){
    const pref = localStorage.getItem(TAMPO_TEMA)||'dark';
    document.body.classList.toggle('light-mode', pref==='light');
    localStorage.setItem(TAMPO_TEMA, pref);
    marcarIcons();
  }
  function marcarIcons(){
    const luna = document.querySelector('.icone-luna');
    const sol  = document.querySelector('.icone-sol');
    if(document.body.classList.contains('light-mode')){
      luna.classList.add('ativo');luna.classList.remove('base');
      sol.classList.add('base');sol.classList.remove('ativo');
    }else{
      luna.classList.remove('ativo');luna.classList.add('base');
      sol.classList.add('ativo');sol.classList.remove('base');
    }
  }
  const BtnTema = document.querySelector('.trocar-tema');
  BtnTema.addEventListener('click', function(){
    const prox = document.body.classList.contains('light-mode') ? 'dark' : 'light';
    document.body.classList.toggle('light-mode', prox==='light');
    localStorage.setItem(TAMPO_TEMA, prox);
    marcarIcons();
  });
  carregarTema();

  /* ═════════ ESTADO GERAL ═════════ */
  let rodando = false;

  function pararAnimacao(btn){
    btn.classList.remove('ativando');
    const sp = btn.querySelector('.spi');
    if(sp) sp.remove();
  }

  /* ═════════ NOTIFICAÇÕES ═════════ */
  const MARCAS = { info:'', sucesso:'sucesso', alerta:'', erro:'erro' };
  function avisar(html, tipo){
    tipo = (tipo||'info').toLowerCase();
    const el = document.createElement('div');
    el.className = 'notif ' + (MARCAS[tipo]||'');
