void DedupZonas(const vector<ZonaOB>& z){
   if(z.size()<2) return;
   sort(z.begin(),z.end(),[](const ZonaOB& a,const ZonaOB& b){return a.base<b.base;});
   vector<ZonaOB>m;
   for(int i=0;i<z.size();i++){
      if(m.empty()){ m.push_back(z[i]); continue; }
      double d=MathAbs(m.back().base-z[i].base);
      if(d>1.5*InpObDiffMin || z[i].topo-m.back().topo>InpObDiffMin*2){ m.push_back(z[i]); }
