bool ConviccaoVela(int bar){
   if(bar<2) return false;
   double c0=g_Buffer[bar], c1=g_Buffer[bar-1], c2=g_Buffer[bar-2];
   double tri=MathMax(g_HBuf[bar]-g_LBuf[bar],0.0);
   if(tri<InpConvMult*CalcATR(11)) return false;

   // pullback curto seguido de continuidade (viés comprador)
   if(c0<c1 && c1<c2 && (c0-c1)<0.75*MathAbs(c2-c1)) return true;
   // recovery que invade vela anterior de baixa (viés comprador)
   if(c0<c1 && MathAbs(c1-c2)>0.6*MathAbs(c2-c1) && c1>c2) return true;
   // espelho viés vendedor
   if(c0>c1 && c1>c2 && (c0-c1)<0.75*MathAbs(c2-c1)) return false; // sinal compra ja dado
   if(c0>c1 && MathAbs(c1-c2)>0.6*MathAbs(c2-c1) && c1<c2) return true;
   return false;
}

bool FormacaoBoa(bool comprar){
   // padroes de reversao curta que indicam quem esta no comando neste momento
   if(comprar){
      // duas altas seguidas e pullback recente curto
      int cnt=0, lastLow=0;
      for(int i=barIdx;i>=1;i--){
         double l=(g_LBuf[i]<0)?0:g_LBuf[i], h=(g_HBuf[i]<0)?0:g_HBuf[i];
         if(h-l<CorpMedia(i-2,i+2)*0.5) continue;
         if(h>lastLow){ lastLow=h; cnt++; if(cnt>=2) return true; }
      }
      // pullback com fundo mais alto que o anterior
      if(g_Buffer[barIdx]<g_Buffer[barIdx-1] && g_Buffer[barIdx]>g_Buffer[barIdx-2]-CorpMedia(barIdx-4,barIdx-2)*0.6)
         return true;
   }
   return false;
}

