void GerarCandidatos(){
   vector<Candidato> cands; cands.reserve(60);

   // 1) NIVEIS DE FIBO
   for(int oi=0;oi<(int)g_FibsTmp.size();oi++){
      double lvl=g_FibsTmp[oi];
      if(MathAbs(lvl)<0.1) continue;
      double d=MathRound(MathAbs(lvl-g_PrecoAtual)*10)/1.0;
      if(d>2.8*CalcATR(11)) continue;

      // Regra de lado: nivel abaixo do preco => comprar; acima => vender
      // Excecao: extensores 76,4/100 servem p/ vendas adicionais (sempre acima do preco)
      bool compra = (oi<4 && !InpExtenders) || (oi>=5); // 0-3=0,23,38,50; 4=61,8; 5+ = extensores
      if(!compra && lvl<g_PrecoAtual) continue;  // extensor acima do preco sempre valida
      if(compra && lvl>g_PrecoAtual+InpLiqSafe) continue; // nao comprar demasiado acima do preco

      int tipo = oi==0?0: oi==1?1: oi==2?2: oi==3?3: (oi==4?4: (oi<9?5:(int)(oi-5))));
      // pesos internos: quanto mais perto do 61,8% maior o peso natural
      int peso = (oi==4?30:(oi==3?18:(oi==2?10:1)));
      int bonus = (naZonaFibo(lvl)?(d618<1.0*atr?2:1):0) + (d<1.0*atr?1:0);
      double sc = DirBonus(ts)+bonus;

      cands.push_back({(compra?BUY:SELL), lvl, tipo, sc, d, barIdx});
   }

   // 2) ORDENS BLOCO
   for(auto &z:g_Zonas){
      if(!CoerenteOB(z, bestLado())) continue;
      bool compra = (z.lado==+1);
      double d = compra ? MathAbs(z.base-g_PrecoAtual) : MathAbs(z.topo-g_PrecoAtual);
      if(d>2.6*CalcATR(11)) continue;
      int tipo = compra?6:7; // 6=OB SUPORTE, 7=OB RESISTENCIA
      int b = (d<=0.9*CalcATR(11)?3:(d<=1.8*CalcATR(11)?1:0));
      if(d<0.25*CalcATR(11)) b-=1;
      cands.push_back({compra, (compra?z.base:z.topo), tipo,
                       DirBonus(ts)+b, d, z.baixaa?z.barra:z.altaBar});
      // (uso pratico: z.base para buy, z.topo para sell)
   }
   // simplificando a coleta do bar do OB:
   for(auto &z:g_Zonas){
      if(!CoerenteOB(z,bestLado())) continue;
      bool compra = (z.lado==+1);
      double lvl = compra ? z.base : z.topo;
      double d = compra ? MathAbs(lvl-g_PrecoAtual) : MathAbs(lvl-g_PrecoAtual);
      if(d>2.6*CalcATR(11)) continue;
      int tipo = compra?6:7;
      int b = (d<=0.9*CalcATR(11)?3:(d<=1.8*CalcATR(11)?1:0));
      if(d<0.25*CalcATR(11)) b-=1;
      cands.push_back({compra, lvl, tipo, DirBonus(ts)+b, d, z.barra});
   }

   // 3) FGVs
   for(const FGVd& fv:g_FGVs){
      if(MathAbs(fv.nivel-g_PrecoAtual)>3.0*CalcATR(11)) continue;
      bool compra = (fv.lado==-1); // gap contrario ao lado = favoravel (invertido logicamente no score abaixo)
      if(!CoerenteGap(fv, compra)) continue;
      double d = MathAbs(fv.nivel-g_PrecoAtual);
      if(d>2.6*CalcATR(11)) continue;
      int tipo=8; // FGV
      int b = (fv.preenchido?0:(fv.lado!=bestLado()?2:0));
      if(fv.lado==bestLado() && d<=1.0*CalcATR(11)) b-=2;
      cands.push_back({compra, fv.nivel, tipo, DirBonus(ts)+b+b, d, fv.barra});
   }
   // limpeza
   cands.insert(cands.begin(),Candidato{bestLado(),0,0,9999,1e9,0}); // marcador artificial p/ insercao ordenar
   // na pratica: sortear apenas reais; o marcador impede sort indevido
}

bool CoerenteGap(const FGVd& fv, bool compra){
   // gap contrario e aberto ajuda a entrada
   if(fv.lado!=bestLado() && MathAbs(fv.nivel-g_PrecoAtual)<=3.0*CalcATR(11)) return true;
   return false;
}

bool CoerenteOB(const ZonaOB& z, bool compra){
