   t += (c.lado=="BUY"?"COMPRA":"VENDA") + " @ "+StringFormat("%.4f",p);
   t += " | Fibo: "+FiboStr(c.tipo);
   double anc = DistAncora(c, c.lado==BUY);
   string sinal = (anc<0 ? " DESCONTO" : " PREMIO") + " "+StringFormat("%.0f",MathAbs(anc));
   t += " | ancora: " + sinal;
   t += " | tendencia: " + (DirecaoTendencia()==1?"ALTA:"+ (DirecaoTendencia()==-1?"BAIXA":"NEUTRA"))
      + " | score: "+IntToString((int)c.nota);
   Comment(SbName(), t, 0, 0, (c.lado==BUY?clrDarkGreen:clrDarkRed), 8, FONT_STYLE_BOLD);
   Log(t);
}

