void ReconstruiHandles(){
   if(!g_TradeActive) return;
   g_Handles.clear();
   for(int pos=0;pos<tr.PositionsCount();pos++){
      if(!MatchesPos(pos)) continue;
      for(int tk=0;tk<tr.TicketCount(pos);tk++){
         long t = tr.GetTicket(pos,tk);
         if(tr.IsOrderSelected(t)){
            if(g_Handles.empty() || g_Handles.back()!=t){
               g_Handles.push_back(tr.GetObject(t).Handle());
            }
         }
      }
   }
}

int PosIndex(){
   for(int pos=0;pos<tr.PositionsCount();pos++){
      if(MatchesPos(pos)) return pos;
   }
   return -1;
}

