void ConferirPendencias(){
   if(tr.BrokerProtectedIn()) tr.BrokerProtectedIn();
   if(!g_TradeActive || g_Handles.empty()) return;
   long h = g_Handles[0];
   if(!tr.IsOrderSelected(h)) return; // ja fechou ou foi cancelada

   if(mtime_now()-g_ModTimes[h] < InpTimeoutOrd*1000) return; // dentro do prazo

   if(tr.IsOrderSelected(h) && mtime_now()-g_ModTimes[h] > InpTimeoutOrd*1000 && InpFallbackMerc){
      CancelPending();
      if(tr.BrokerProtectedIn()){
         double p = MathRound(g_CandCand.nivel, DecimalDigits());
         long oh = tr.Order(g_Symb, ORDER_TYPE_MARKET, p, InpComPrefix+" FALLBACK MERCADO ", NULL, InpLot, 0,0,0,0);
         if(oh>0){
            g_HandleCurHandle = oh; g_CloseTime=0;
            Log("FAILLBACK MERCADO enviado @ "+StringFormat("%.4f",p));
         }
      }
      return;
   }
   if(tr.IsRateLimitExceeded()) return;
}

